SettlementView : {
 "type": "object",
 "required": [
  "episode_id",
  "outcome",
  "final_votes",
  "winner_id",
  "winner_payout",
  "juror_payouts",
  "protocol_fee",
  "forfeited_bonds",
  "refunds",
  "total_deposited",
  "total_credited",
  "deployment"
 ],
 "properties": {
  "deployment": {
   "$ref": "#/components/schemas/DeploymentView"
  },
  "episode_id": {
   "type": "string"
  },
  "final_votes": {
   "type": "object",
