    "$ref": "#/components/schemas/Verdict"
   },
   "propertyNames": {
    "type": "string"
   }
  },
  "forfeited_bonds": {
   "type": "object",
   "additionalProperties": {
    "type": "string",
    "pattern": "^(0|[1-9][0-9]*)$"
   }
  },
  "juror_payouts": {
   "type": "object",
   "additionalProperties": {
    "type": "string",
    "pattern": "^(0|[1-9][0-9]*)$"
   }
  },
  "outcome": {
   "type": "string",
   "enum": [
    "REGISTERED",
    "OPEN",
    "COMMIT",
    "REVEAL",
    "SETTLED_CREATOR",
    "SETTLED_CHALLENGER",
    "ABORTED",
    "EXPIRED_UNCHALLENGED",
    "EXPIRED_UNFUNDED"
   ]
  },
  "protocol_fee": {
   "type": "string",
   "pattern": "^(0|[1-9][0-9]*)$"
  },
  "refunds": {
   "type": "object",
   "additionalProperties": {
    "type": "string",
    "pattern": "^(0|[1-9][0-9]*)$"
   }
  },
  "total_credited": {
   "type": "string",
   "pattern": "^(0|[1-9][0-9]*)$"
  },
  "total_deposited": {
   "type": "string",
   "pattern": "^(0|[1-9][0-9]*)$"
  },
  "winner_id": {
   "type": [
    "string",
    "null"
   ]
  }
