OperationView : {
 "type": "object",
 "required": [
  "operation_id",
  "episode_id",
  "actor_id",
  "kind",
  "status",
  "transaction",
  "error"
 ],
 "properties": {
  "actor_id": {
   "type": "string"
  },
  "episode_id": {
   "type": "string"
  },
  "error": {
   "type": [
    "string",
    "null"
   ]
  },
  "kind": {
   "type": "string"
  },
  "operation_id": {
   "type": "string"
  },
  "status": {
   "type": "string",
   "enum": [
    "accepted",
    "prepared",
    "submitted",
    "included",
    "confirmed",
    "reverted",
    "failed"
   ]
  },
  "transaction": {
   "oneOf": [
    {
     "type": "null"
    },
    {
     "$ref": "#/components/schemas/TransactionView"
    }
   ]
  }
 }
}
