  "entitlements": {
   "type": "object",
   "additionalProperties": {
    "type": "string",
    "pattern": "^(0|[1-9][0-9]*)$"
   }
  },
  "episode_id": {
   "type": "string"
  },
  "withdrawal_credits": {
   "type": "object",
   "additionalProperties": {
    "type": "string",
    "pattern": "^(0|[1-9][0-9]*)$"
   }
  }
 }
}
