ReceiptView : {
 "type": "object",
 "required": [
  "transaction_hash",
  "success",
  "block_number",
  "block_hash",
  "gas_used",
  "effective_gas_price",
  "confirmations",
  "confirmed"
 ],
 "properties": {
  "block_hash": {
   "type": "string"
  },
  "block_number": {
   "type": "integer",
   "format": "int64",
   "minimum": 0
  },
  "confirmations": {
   "type": "integer",
   "format": "int64",
   "minimum": 0
  },
  "confirmed": {
   "type": "boolean"
  },
  "effective_gas_price": {
   "type": "string",
   "pattern": "^(0|[1-9][0-9]*)$"
  },
  "gas_used": {
   "type": "string",
   "pattern": "^(0|[1-9][0-9]*)$"
  },
  "success": {
   "type": "boolean"
  },
  "transaction_hash": {
   "type": "string"
  }
 }
}
